import { getTranslations } from "next-intl/server";

import { ComplianceCockpitView } from "./ui";

export async function generateMetadata() {
  const t = await getTranslations("compliance");
  return { title: t("navTitle") };
}

/** /compliance — thin route; the bridge is generated by `pnpm module:sync`. */
export default function CompliancePage({ searchParams }: { searchParams: Promise<{ year?: string; preview?: string }> }) {
  return <ComplianceCockpitView searchParams={searchParams} />;
}
